/** One style of a vendored substitute font (generated by scripts/make-font-subsets.py). */
export interface SubstituteStyle {
  postScriptName: string
  /** Standard-14 font this style is metric-compatible with. */
  coreFont: string
  unitsPerEm: number
  /** Font bounding box, glyph space (1/1000 em). */
  bbox: number[]
  italicAngle: number
  ascent: number
  descent: number
  capHeight: number
  stemV: number
  /** Adobe AFM widths of `coreFont`: "glyphName width" pairs separated by spaces. */
  coreWidths: string
  /** TrueType subset program, base64. */
  program: string
}

export type FontStyle = "regular" | "bold" | "italic" | "boldItalic"

export interface SubstituteFamily {
  name: string
  serif: boolean
  fixedPitch: boolean
  styles: Record<FontStyle, SubstituteStyle>
}

/** A non-embedded font replaced by an embedded, metric-compatible substitute. */
export interface ReplacedFont {
  /** BaseFont of the original font, without subset prefix (e.g. `Helvetica-Bold`). */
  original: string
  /** PostScript name of the substitute (e.g. `Arimo-Bold`). */
  substitute: string
  /** 1-based pages where the font is used. */
  pages: number[]
}

/** A non-embedded font left as is: the output cannot be PDF/A conformant. */
export interface UnrepairableFont {
  name: string
  /** French, user-facing. */
  reason: string
}

export interface FontRepairReport {
  fontsReplaced: ReplacedFont[]
  fontsUnrepairable: UnrepairableFont[]
}
